import {FirstBatchHeader} from '../mobile/FirstBatchHeader';
import React, {useEffect, useMemo, useRef, useState} from 'react';
import {workspaceAuth, api} from './auth';
import {dimensions as sourceDimensions, oneCondition, summarize as sourceSummarize, cohorts as sourceCohorts, selectSessions as sourceSelectSessions} from './analysis.mjs';
