const logo = new URL('../../public/ui/logo-mark.png', import.meta.url).href;
type Role = 'coach' | 'admin';
type Page = 'overview' | 'members' | 'trainings' | 'groups' | 'compare' | 'trends' | 'notes' | 'reports' | 'announcements' | 'session';
type CoachStatus = 'pending' | 'approved' | 'suspended' | 'rejected';
type Me = {roles: string[]; coach: {status: CoachStatus; name?: string; organisation?: string; reason?: string} | null};
type Coach = {userId: string; name: string; organisation: string; status: CoachStatus; version: number; applicationNote?: string; reason?: string; phoneDisplay?:string};
type Team = {id: string; name?: string; label?: string};
type Member = {id: string; userId?: string; label: string; status: 'invited' | 'pending' | 'active' | 'inactive'; sharingStatus: 'shared' | 'not-shared' | 'revoked' | 'expired'; category: 'men' | 'women' | 'unknown'; version: number; sharedCount?: number};
type Conditions = {bow: string; distance: number; size: number | null; targetId: string; targetName: string; rulesVersion: string};
type Session = {id: string; memberId: string; revision: number; date: string; groupKey: string | null; conditions: Conditions;
  summary: {arrows: number; total: number; average: number; trustedPoints: number; distribution: Record<string, number>};
  ends: {index: number; codes: string[]; half?: string}[];
  targetFace: null | {name: string; faceCount: number; rings: {code: string; color: string; radius: number}[]; layout: {kind: string; faces: {index: number; anchor_x: number; anchor_y: number}[]}};
  points: {x: number; y: number; code: string; face: number; endIndex: number; arrowIndex: number}[]};
type Note = {memberId: string; sessionId: string; sourceRevision: number; version: number; text: string; updatedAt?: string};
type GroupConfig = {bow: string; distance: number; size: number; targetId: string; ends: number; arrowsPerAthlete: number; scoring: 'set' | 'cumulative'};
type Group = {id: string; version: number; name: string; kind: 'mixed' | 'men' | 'women'; memberIds: string[]; preset: string; config: GroupConfig};
type Review = {team: Team; members: Member[]; sessions: Session[]; groups: Group[]; notes: Note[]; generatedAt: string};
type Filter = {from: string; to: string; bow: string; distance: string; targetId: string; size: string; rulesVersion: string; squad: string; member: string; query: string};
type Route = {role: Role; page: Page; query: URLSearchParams};
type NoteDraft = {text: string; expectedVersion: number; sourceRevision: number};
type GroupDraft = Omit<Group, 'id' | 'version'> & {id: string | null; expectedVersion: number};
const pages: {id: Exclude<Page, 'session'>; label: string; description: string}[] = [
  {id:'overview', label:'团队总览', description:'掌握共享训练与待核对事项'},
  {id:'members', label:'队员', description:'核对成员与成绩共享状态'},
  {id:'trainings', label:'训练列表', description:'按日期、队员和训练条件查看已共享记录'},
  {id:'groups', label:'比赛编组', description:'安排参赛队员和训练条件'},
  {id:'compare', label:'同条件对比', description:'相同训练条件下的队员描述统计'},
  {id:'trends', label:'个人趋势', description:'按训练条件分别查看个人变化'},
  {id:'notes', label:'教练复盘', description:'查看落点、成绩和复盘进度'},
  {id:'reports', label:'周报导出', description:'按当前范围生成分条件汇总'},
  {id:'announcements', label:'团队公告', description:'查看已向教练发布的公告和版本说明'},
];
const iconPaths: Record<string, string> = {
  overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  members:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 8h5 M19.5 5.5v5',
  trainings:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4 M8 14h2 M14 14h2 M8 18h2',
  groups:'M4 16h5v5H4z M15 16h5v5h-5z M9 3h6v5H9z M12 8v4 M6.5 16v-4h11v4',
  compare:'M5 21V10 M12 21V3 M19 21V7 M3 21h18',
  trends:'M3 3v18h18 M6 16l5-5 4 2 6-8',
  notes:'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h3',
  reports:'M5 3h10l4 4v14H5z M14 3v5h5 M12 11v7 M9 15l3 3 3-3',
  announcements:'M4 7l13-4v16L4 15z M5 15l1 6h3l-1-5',
  admin:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',
  back:'M20 12H4 M10 6l-6 6 6 6', logout:'M9 3H4v18h5 M9 12h12 M17 8l4 4-4 4',
};
function Icon({name}: {name: string}) {return <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={iconPaths[name] || iconPaths.overview}/></svg>;}
const emptyFilter = (): Filter => ({from:'',to:'',bow:'',distance:'',targetId:'',size:'',rulesVersion:'',squad:'',member:'',query:''});
type Summary = {sessions:number;arrows:number;score:number;points:number;X:number;ten:number;M:number;average:number|null};
const analysis={dimensions:sourceDimensions,oneCondition,summarize:sourceSummarize,cohorts:sourceCohorts,selectSessions:sourceSelectSessions} as unknown as {
  dimensions:readonly (readonly ['bow'|'distance'|'targetId'|'size'|'rulesVersion',string])[];
  oneCondition:(rows:Session[])=>boolean;
  summarize:(rows:Session[])=>Summary;
  cohorts:(rows:Session[])=>Session[][];
  selectSessions:(rows:Session[],query:URLSearchParams,memberIds?:string[]|null)=>Session[];
};
const dimensions = analysis.dimensions;
const statusText: Record<string,string> = {pending:'待审核',approved:'已批准',suspended:'已暂停',rejected:'未通过',active:'已核对',inactive:'已停用',invited:'待加入',shared:'共享中','not-shared':'未共享',revoked:'已撤销',expired:'已到期'};
const memberLabel = (members: Member[], id: string) => members.find(m=>m.id===id)?.label || '当前不可用的队员';
const teamLabel = (team: Team) => team.name || team.label || '我的团队';
const number = (n: number | null, digits=2) => n === null || !Number.isFinite(n) ? '—' : n.toLocaleString('zh-CN',{maximumFractionDigits:digits});
const conditionsLabel = (c: Conditions) => `${c.bow} · ${c.distance}m · ${c.size ?? '未知'}cm · ${c.targetName}`;
const conditionKey = (s: Session) => s.groupKey || `unknown:${s.memberId}:${s.id}`;
const canCompare = analysis.oneCondition;
const summarize = (rows:Session[]) => {const summary=analysis.summarize(rows);return {...summary,total:summary.score};};
const cohorts = analysis.cohorts;
function selectSessions(data: Review, f: Filter) {
  const group=data.groups.find(g=>g.id===f.squad);if(f.squad&&!group)return [];
  if(f.from&&f.to&&f.from>f.to)return [];
  return analysis.selectSessions(data.sessions,new URLSearchParams(f),group?.memberIds).filter(s=>(!f.member||s.memberId===f.member)
    &&(!f.query||[memberLabel(data.members,s.memberId),s.date,conditionsLabel(s.conditions)].join(' ').toLocaleLowerCase().includes(f.query.toLocaleLowerCase())))
    .sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id));
}
function route(): Route {const [path,search='']=location.hash.slice(1).split('?');const parts=path.split('/').filter(Boolean);return {role:parts[0]==='admin'?'admin':'coach',page:pages.some(p=>p.id===parts[1])||parts[1]==='session'?parts[1] as Page:'overview',query:new URLSearchParams(search)};}
function leaveAdminRoute(){if(route().role!=='admin')return;history.replaceState(history.state,'',location.pathname+location.search+'#/coach');dispatchEvent(new HashChangeEvent('hashchange'));}
function hash(page: Page, query?: URLSearchParams) {return `#/coach/${page}${query?.size?'?'+query.toString():''}`;}
function publicQuery(query: URLSearchParams) {const next=new URLSearchParams();for(const key of Object.keys(emptyFilter()))if(query.get(key))next.set(key,query.get(key)!);return next;}
function menuQuery(page:Page,query:URLSearchParams) {if(['groups','members'].includes(page))return new URLSearchParams();const next=publicQuery(query);if(['compare','reports','overview'].includes(page))next.delete('member');if(!['trainings','notes'].includes(page))next.delete('query');return next;}
function filterFrom(query: URLSearchParams): Filter {return Object.fromEntries(Object.keys(emptyFilter()).map(k=>[k,query.get(k)||''])) as Filter;}
function errorCode(error: unknown) {
  const value=error as {status?: unknown; code?: unknown}|null;
  return {
    status:typeof value?.status==='number'?value.status:undefined,
    code:typeof value?.code==='string'?value.code:undefined,
  };
}
const readOnlyFailures=new WeakSet<object>();
function errorMessage(error: unknown) {
  const {status,code}=errorCode(error);
  const readOnly=!!error&&typeof error==='object'&&readOnlyFailures.has(error);
  // Only exact server-owned fixed details are projected; arbitrary response text
  // is never shown. Codes identify a layer, not a person or database object.
  if(status===503){
    const detail=error instanceof Error?error.message:'';
    const known:Record<string,string>={
      '团队工作台尚未开放':'团队服务尚未开放，请稍后重试。（T01）',
      '团队数据权限尚未就绪':'团队数据校验暂未通过，请稍后重试。（T02）',
      '团队身份验证尚未接入':'团队账号核验暂不可用，请稍后重试。（T03）',
      '私密数据通道尚未就绪':'团队数据保护通道暂不可用，请稍后重试。（T04）',
      '团队存储尚未就绪':'团队存储尚未就绪，请稍后重试。（T05）',
      '团队存储暂不可用，请读取状态后核对':'团队存储暂不可用，请稍后重新核对。（T06）',
      '认证服务尚未配置':'账号验证服务暂不可用，请稍后重试。（T07）',
      '认证公钥暂时不可用':'账号验证连接暂不可用，请稍后重试。（T08）',
      '认证公钥格式无效':'账号验证配置暂不可用，请稍后重试。（T09）',
      '测试账号的手机验证门禁尚未接入':'手机号核验暂不可用，请稍后重试。（T10）',
    };
    if(Object.prototype.hasOwnProperty.call(known,detail))return readOnly?known[detail]:known[detail].replace(/请稍后(?:重新核对|重试)。/, '请先刷新核对，确认后再提交。');
  }
  if(status===403)return '当前权限已不可用，请重新核对账号或联系管理员。';
  if(status===401)return '登录状态已失效，请重新登录。';
  if(status===409)return '记录已更新，请刷新后核对内容再保存。';
  if(status===404)return '这条记录已不可访问，请返回列表刷新。';
  if(code==='OUTCOME_UNKNOWN'||code?.includes('UNKNOWN'))return readOnly?'本次读取结果尚未确认，请重新核对。':'操作结果尚未确认，请先刷新核对，不要重复提交。';
  if(readOnly)return '本次读取未完成，请检查连接后重新核对。';
  return '暂时无法完成操作，请检查连接后重试。';
}
const permissionLost=new EventTarget();
const identityKey=()=>JSON.stringify(api.identity());
async function request<T>(path:string,method:'GET'|'POST'|'PUT'='GET',body?:unknown):Promise<T>{
  const expected=identityKey();
  try{return await api.request<T>(`/api/team${path}`,method,body);}catch(error){
    if(method==='GET'&&error&&typeof error==='object')readOnlyFailures.add(error);
    if(expected===identityKey()&&path!=='/me'&&[401,403].includes(errorCode(error).status||0))permissionLost.dispatchEvent(new Event('lost'));
    throw error;
  }
}
async function readWorkspacePermissions(stillCurrent:()=>boolean):Promise<Me>{
  try{
    return await request<Me>('/me');
  }catch(error){
    const {status}=errorCode(error);
    const transient=error instanceof TypeError
      ||error instanceof DOMException&&['AbortError','TimeoutError'].includes(error.name)
      ||status===502||status===504;
    if(!transient||!stillCurrent())throw error;
    await new Promise(resolve=>setTimeout(resolve,350));
    if(!stillCurrent())throw error;
    return request<Me>('/me');
  }
}
function Panel({title,action,children}: {title?: string;action?: React.ReactNode;children: React.ReactNode}) {return <section className="ws-card">{title&&<div className="ws-card-head"><h2>{title}</h2>{action}</div>}<div className="ws-card-body">{children}</div></section>;}
function Empty({title,children}: {title: string;children?: React.ReactNode}) {return <div className="ws-empty"><Icon name="notes"/><h2>{title}</h2>{children&&<p>{children}</p>}</div>;}
function Notice({children,error=false}: {children: React.ReactNode;error?: boolean}) {return children?<div className={`ws-notice${error?' error':''}`} role={error?'alert':'status'}>{children}</div>:null;}
function Badge({value}: {value:string}) {return <span className={`ws-badge ${['shared','active','approved'].includes(value)?'good':['pending','suspended','expired'].includes(value)?'warn':''}`}>{statusText[value] || value}</span>;}
function Application({me,onRefresh}: {me:Me;onRefresh:()=>void}) {
  const application=me.coach,[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[name,setName]=useState(application?.name||''),[organisation,setOrganisation]=useState(application?.organisation||''),[note,setNote]=useState('');
  async function submit(e:React.FormEvent) {e.preventDefault();setBusy(true);setNotice('');try{await request('/coach-application','POST',{name:name.trim(),organisation:organisation.trim(),note:note.trim()});onRefresh();}catch(error){setNotice(errorMessage(error));}finally{setBusy(false);}}
  if(application&&application.status!=='rejected')return <><FirstBatchHeader eyebrow="团队工作台 / 权限" title="教练申请" description="当前账号的申请进度与审核说明。"/><Panel><Empty title={application.status==='pending'?'申请正在审核':application.status==='suspended'?'教练权限已暂停':'正在核对教练权限'}>{application.reason||'审核状态会在这里更新。'}</Empty><button onClick={onRefresh}>刷新申请状态</button></Panel></>;
  return <><FirstBatchHeader eyebrow="团队工作台 / 权限" title="教练申请" description="提交所属组织和申请资料后，可在此查看审核进度。"/><Panel title={application?'重新提交教练申请':'申请教练权限'}><p className="ws-help">填写真实姓名和所属学校、俱乐部或团队，等待管理员审核。</p><Notice error>{notice}</Notice>{application?.reason&&<Notice>上次审核说明：{application.reason}</Notice>}<form className="ws-form" onSubmit={submit}><fieldset disabled={busy}><label>姓名<input required maxLength={60} value={name} onChange={e=>setName(e.target.value)}/></label><label>所属组织<input required maxLength={120} value={organisation} onChange={e=>setOrganisation(e.target.value)}/></label><label>申请说明<textarea maxLength={1000} rows={4} value={note} onChange={e=>setNote(e.target.value)}/></label><button className="primary">{busy?'提交中…':'提交申请'}</button></fieldset></form></Panel></>;
}
function AdminWorkspace() {
  const [coaches,setCoaches]=useState<Coach[]|null>(null),[filter,setFilter]=useState<CoachStatus>('pending'),[error,setError]=useState(''),[notice,setNotice]=useState(''),[loading,setLoading]=useState(false),[selected,setSelected]=useState<Coach|null>(null),[reason,setReason]=useState(''),[busy,setBusy]=useState(false);
  const generation=useRef(0),mounted=useRef(true),lock=useRef(false);
  useEffect(()=>{mounted.current=true;void refresh();return()=>{mounted.current=false;generation.current++;};},[]);
  async function refresh() {const token=++generation.current;setLoading(true);setError('');setCoaches(null);setSelected(null);try{const value=await request<{items:Coach[]}>('/admin/coaches');if(mounted.current&&token===generation.current)setCoaches(value.items);}catch(e){if(mounted.current&&token===generation.current){setCoaches(null);setError(errorMessage(e));}}finally{if(mounted.current&&token===generation.current)setLoading(false);}}
  async function update(status:CoachStatus) {if(!selected||lock.current)return;lock.current=true;setBusy(true);setNotice('');const token=generation.current;try{await request(`/admin/coaches/${encodeURIComponent(selected.userId)}`,'PUT',{status,expectedVersion:selected.version,reason:reason.trim()});if(mounted.current&&token===generation.current){setReason('');setNotice('教练状态已更新。');await refresh();}}catch(e){if(mounted.current&&token===generation.current){if([401,403].includes(errorCode(e).status||0)){setCoaches(null);setSelected(null);}setError(errorMessage(e));}}finally{lock.current=false;if(mounted.current)setBusy(false);}}
  const rows=(coaches||[]).filter(c=>c.status===filter);
  return <><FirstBatchHeader eyebrow="管理工作台 / 角色权限" title="教练审核" description="核对所属组织和申请说明，按当前状态处理教练权限。"/><div className="ws-toolbar"><button disabled={loading||busy} onClick={()=>void refresh()}>{loading?'读取中…':'刷新教练名单'}</button></div><Notice error>{error}</Notice><Notice>{notice}</Notice><Panel><div className="ws-tabs" aria-label="教练状态">{(['pending','approved','suspended','rejected'] as const).map(s=><button key={s} disabled={busy} aria-pressed={filter===s} className={filter===s?'selected':''} onClick={()=>{setFilter(s);setSelected(null);setReason('');}}>{statusText[s]}{coaches&&` ${coaches.filter(c=>c.status===s).length}`}</button>)}</div>{loading?<Empty title="正在读取教练名单"/>:coaches===null?<Empty title="没有可显示的审核数据"/>:rows.length?<div className="ws-table-wrap"><table><thead><tr><th>姓名 / 账号</th><th>组织</th><th>状态</th><th>操作</th></tr></thead><tbody>{rows.map(c=><tr key={c.userId}><td>{c.name}<small className="ws-help">{c.phoneDisplay||'已验证账号'}</small></td><td>{c.organisation}</td><td><Badge value={c.status}/></td><td><button disabled={busy} onClick={()=>{setSelected(c);setReason('');}}>审核详情</button></td></tr>)}</tbody></table></div>:<Empty title="此状态暂无教练"/>}</Panel>{selected&&<Panel title={`${selected.name} · 审核详情`} action={<button disabled={busy} onClick={()=>setSelected(null)}>收起</button>}><dl className="ws-facts"><div><dt>账号</dt><dd>{selected.phoneDisplay||'已验证账号'}</dd></div><div><dt>所属组织</dt><dd>{selected.organisation}</dd></div><div><dt>申请说明</dt><dd>{selected.applicationNote||'未填写'}</dd></div></dl><label>审核说明<textarea disabled={busy} maxLength={500} rows={3} value={reason} onChange={e=>setReason(e.target.value)}/></label><div className="ws-actions">{selected.status==='pending'&&<><button className="primary" disabled={busy} onClick={()=>void update('approved')}>批准申请</button><button className="danger" disabled={busy||!reason.trim()} onClick={()=>void update('rejected')}>不通过</button></>}{selected.status==='approved'&&<button className="danger" disabled={busy||!reason.trim()} onClick={()=>void update('suspended')}>暂停教练权限</button>}{selected.status==='suspended'&&<button className="primary" disabled={busy||!reason.trim()} onClick={()=>void update('approved')}>恢复教练权限</button>}<span className="ws-help">暂停、不通过或恢复时请填写原因。</span></div></Panel>}</>;
}
function Filters({data,value,onApply,report=false,initiallyCollapsed=false}: {data:Review;value:Filter;onApply:(next:Filter)=>void;report?:boolean;initiallyCollapsed?:boolean}) {
  const [expanded,setExpanded]=useState(()=>!initiallyCollapsed&&(report||!window.matchMedia('(max-width: 800px)').matches));
  const count=Object.values(value).filter(Boolean).length;
  const [draft,setDraft]=useState(value);useEffect(()=>setDraft(value),[JSON.stringify(value)]);
  const [error,setError]=useState('');const change=(key:keyof Filter,v:string)=>setDraft(d=>({...d,[key]:v}));
  return <details className="ws-range" open={expanded} onToggle={e=>setExpanded(e.currentTarget.open)}><summary>筛选范围 <span>{count?`已应用 ${count} 项`:'全部已共享训练'}</span></summary><Panel title="调整条件" action={<button className="text-button" onClick={()=>{const clean={...emptyFilter(),member:value.member};setDraft(clean);setError('');onApply(clean);}}>清除条件</button>}><form onSubmit={e=>{e.preventDefault();if(draft.from&&draft.to&&draft.from>draft.to){setError('结束日期不能早于开始日期。');return;}setError('');onApply(draft);if(initiallyCollapsed||!report&&window.matchMedia('(max-width: 800px)').matches)setExpanded(false);}}><div className="ws-filter-grid">{!report&&<label>队员<select value={draft.member} onChange={e=>change('member',e.target.value)}><option value="">全部队员</option>{draft.member&&!data.members.some(m=>m.id===draft.member)&&<option value={draft.member}>当前不可访问的队员</option>}{data.members.map(m=><option key={m.id} value={m.id}>{m.label}</option>)}</select></label>}<label>参赛分组<select value={draft.squad} onChange={e=>change('squad',e.target.value)}><option value="">全部分组</option>{draft.squad&&!data.groups.some(g=>g.id===draft.squad)&&<option value={draft.squad}>当前不可访问的分组</option>}{data.groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label><label>起始日期<input type="date" value={draft.from} onChange={e=>change('from',e.target.value)}/></label><label>结束日期（含）<input type="date" value={draft.to} onChange={e=>change('to',e.target.value)}/></label></div><details className="ws-filter-details"><summary>训练条件 · 各维度独立选择</summary><div className="ws-filter-grid conditions">{dimensions.map(([key,label])=>{const choices=new Map<string,string>();for(const s of data.sessions){const v=String(s.conditions[key]??'unknown');choices.set(v,key==='targetId'?s.conditions.targetName:key==='rulesVersion'?v==='未知规则'?v:'已知规则 '+v:v==='unknown'?'未知':v+(key==='distance'?'m':key==='size'?'cm':''));}if(draft[key]&&!choices.has(draft[key]))choices.set(draft[key],`${draft[key]}（当前无记录）`);return <label key={key}>{label}<select value={draft[key]} onChange={e=>change(key,e.target.value)}><option value="">全部</option>{[...choices].map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label>;})}</div></details><div className="ws-filter-bottom">{!report&&<label className="ws-search">搜索记录<input placeholder="队员、日期或训练条件" value={draft.query} onChange={e=>change('query',e.target.value)}/></label>}<button className="primary">应用筛选</button></div><Notice error>{error}</Notice></form></Panel></details>;
}
