    {current.page==='trends'&&(f.member?<Trend rows={rows}/>:<Panel><Empty title="先选择一名队员">使用上方队员筛选查看个人趋势。</Empty></Panel>)}
    {current.page==='notes'&&<Panel title="复盘清单" action={<label className="ws-compact-label">复盘状态<select value={reviewState} onChange={e=>setReviewState(e.target.value)}><option value="">全部</option><option value="pending">待复盘</option><option value="done">已写备注</option><option value="changed">训练已更新</option></select></label>}><SessionTable notes rows={rows.filter(s=>{const n=data.notes.find(n=>n.memberId===s.memberId&&n.sessionId===s.id);return !reviewState||reviewState===(!n?.text?'pending':n.sourceRevision!==s.revision?'changed':'done');})} data={data} open={open}/></Panel>}
